const modules={finanzas:{title:'Una visión clara de sus finanzas.',text:'Organice la información contable y financiera para acompañar las decisiones de su empresa.',items:['Contabilidad general','Cuentas por cobrar','Cuentas por pagar','Tesorería y bancos','Presupuesto']},inventarios:{title:'Una operación mejor organizada.',text:'Conecte la gestión de sus productos con los procesos de compra, venta y facturación.',items:['Facturación electrónica','Punto de venta (POS)','Gestión de compras y ventas','Artículos compuestos','Reportería configurable']},personas:{title:'Su equipo, en el centro.',text:'Reúna los procesos de administración de personal y facilite las tareas de recursos humanos.',items:['Administración de personal','Horarios y reloj marcador','Gestión de vacaciones','Comprobantes de pago por correo']},activos:{title:'Cada activo, bajo control.',text:'Administre la información de sus activos y su relación con la contabilidad de la empresa.',items:['Información de los activos','Depreciación integrada','Compras de activos','Liquidaciones de activos']}};
const tabs=[...document.querySelectorAll('[data-module]')];function selectModule(tab){tabs.forEach(t=>{t.setAttribute('aria-selected',String(t===tab));t.tabIndex=t===tab?0:-1;const status=t.querySelector('.tab-status');if(status)status.textContent=t===tab?'Activo':'Ver'});const m=modules[tab.dataset.module];const panel=document.getElementById('module-panel');panel.setAttribute('aria-labelledby',tab.id);panel.innerHTML=`<p class="eyebrow">ENLACE SOFT® / ${tab.dataset.module==='personas'?'RECURSOS HUMANOS':tab.dataset.module.toUpperCase()}</p><h3>${m.title}</h3><p>${m.text}</p><ul>${m.items.map(item=>`<li>${item}</li>`).join('')}</ul><a class="text-link" href="#contacto" data-consult="Módulo ${({finanzas:'Finanzas',inventarios:'Inventarios',personas:'Recursos humanos',activos:'Activos fijos'})[tab.dataset.module]}">Consultar por este módulo</a>`;document.dispatchEvent(new CustomEvent('modulechange',{detail:tab.dataset.module}));}tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>selectModule(tab));tab.addEventListener('keydown',e=>{let n;if(['ArrowDown','ArrowRight'].includes(e.key))n=(i+1)%tabs.length;if(['ArrowUp','ArrowLeft'].includes(e.key))n=(i+tabs.length-1)%tabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=tabs.length-1;if(n!==undefined){e.preventDefault();selectModule(tabs[n]);tabs[n].focus()}})});selectModule(tabs[0]);
const sectors={Otros:['Una solución para su sector.','Consulte las opciones de enlace soft® y los desarrollos a la medida para los procesos particulares de su empresa.'],Comercio:['De la compra a la venta, una operación conectada.','Explore herramientas de inventarios, compras, facturación electrónica y punto de venta junto con la gestión financiera.'],Construcción:['Información para acompañar sus proyectos.','Consulte las versiones para proyectos y las herramientas financieras, de inventarios y de administración de personal para su operación.'],Contabilidad:['La información contable, en un mismo lugar.','Explore contabilidad general, cuentas por cobrar y pagar, tesorería y presupuesto para su empresa o práctica contable.'],Agro:['Tecnología que entiende el trabajo en el campo.','Análisis MBC desarrolla soluciones para el sector agrícola, incluyendo pineapple+, complementadas con la gestión de enlace soft®.'],Producción:['Herramientas para su operación productiva.','Conozca las opciones de producción, formulación de artículos compuestos, inventarios y gestión financiera.']};document.querySelectorAll('[data-sector]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-sector]').forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',String(b===button))});const [title,text]=sectors[button.dataset.sector];document.getElementById('sector-title').textContent=title;document.getElementById('sector-text').textContent=text}));
document.getElementById('contact-form').addEventListener('submit',e=>{
  e.preventDefault();
  const d=new FormData(e.target);
  const channel=e.submitter?.value==='whatsapp'?'whatsapp':'email';
  const name=String(d.get('nombre')||'').trim();
  const company=String(d.get('empresa')||'').trim();
  const email=String(d.get('correo')||'').trim();
  const message=String(d.get('mensaje')||'').trim();
  if(!name||!message){document.getElementById('form-status').textContent='Complete su nombre y el mensaje de consulta.';return;}
  const body=['Hola, quisiera información sobre las soluciones y servicios de Análisis MBC.','',
    'Nombre: '+name,company?'Empresa: '+company:'',email?'Correo: '+email:'','',message
  ].filter((line,i)=>line||i===1).join('\n');
  const destination=channel==='whatsapp'
    ?'https://wa.me/50686950367?text='+encodeURIComponent(body)
    :'mailto:contacto@analisis.cr?subject='+encodeURIComponent('Consulta Análisis MBC'+(company?' — '+company:''))+'&body='+encodeURIComponent(body);
  const link=document.createElement('a');link.href=destination;
  if(channel==='whatsapp'){link.target='_blank';link.rel='noopener noreferrer';}
  document.body.append(link);link.click();link.remove();
  document.getElementById('form-status').textContent=channel==='whatsapp'
    ?'Consulta preparada para WhatsApp. Revise el mensaje y confirme el envío en la aplicación que se abra.'
    :'Consulta preparada para correo. Revísela y envíela desde su aplicación. Si no se abre, escriba a contacto@analisis.cr o use WhatsApp.';
});document.getElementById('year').textContent=new Date().getFullYear();
